import{_ as e,o,c as t,a3 as n}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Manter agendamento da minuta automaticamente","description":"","frontmatter":{"title":"Manter agendamento da minuta automaticamente","id":"eproc-auto-manter-agendamento","plataforma":"eproc","grupo":"Árvore e minuta","plano":"free","desde":"1.1.0","padrao":"desligado"},"headers":[],"relativePath":"funcionalidades/eproc-auto-manter-agendamento.md","filePath":"funcionalidades/eproc-auto-manter-agendamento.md"}'),r={name:"funcionalidades/eproc-auto-manter-agendamento.md"};function d(s,a,i,u,c,m){return o(),t("div",null,a[0]||(a[0]=[n('<h1 id="manter-agendamento-da-minuta-automaticamente" tabindex="-1">Manter agendamento da minuta automaticamente <a class="header-anchor" href="#manter-agendamento-da-minuta-automaticamente" aria-label="Permalink to &quot;Manter agendamento da minuta automaticamente&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Clica sozinho no botão <strong>Manter Agendamento</strong> da minuta assim que ele aparece, para você não precisar confirmar o agendamento a cada vez.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, em qualquer tela em que o botão &quot;Manter Agendamento&quot; apareça, inclusive dentro de janelas internas.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Ligue o recurso nas configurações do eploc (ele vem desligado), ou use a dica que aparece ao lado do botão &quot;Manter Agendamento&quot; enquanto o recurso está desligado: ela liga o recurso ali mesmo.</li><li>A partir daí, o botão é clicado automaticamente sempre que aparecer.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Mostrar sugestão para ativar esta funcionalidade ao lado do botão &#39;Manter Agendamento&#39;</td><td>ligada</td><td>Só aparece enquanto o recurso está desligado. Também pode ser dispensada pela própria dica (&quot;Não sugerir mais&quot;).</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Com o recurso ligado, todo agendamento é mantido sem confirmação sua. Se em algum caso você não quiser manter, desligue o recurso antes de abrir a minuta.</li></ul>',11)]))}const h=e(r,[["render",d]]);export{p as __pageData,h as default};
